<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { ElMessage, ElMessageBox } from 'element-plus';
import http from '../api/http';
const route=useRoute(); const loading=ref(false),error=ref(''),rows=ref<Record<string,any>[]>([]),total=ref(0),visible=ref(false),editing=ref<Record<string,any>|null>(null);
const key=computed(()=>String(route.path.split('/').pop()));
const meta=computed(()=>({hospital:{title:'医院信息',endpoint:'/admin/master/hospitals',permission:'hospital:info:update'},campuses:{title:'院区楼宇',endpoint:'/admin/master/campuses',permission:'hospital:campus:manage'},departments:{title:'医疗科室',endpoint:'/admin/master/departments',permission:'hospital:department:manage'},doctors:{title:'医生管理',endpoint:'/admin/master/doctors',permission:'hospital:doctor:manage'},dictionaries:{title:'职称、专业与门诊类型',endpoint:'/admin/master/titles',permission:'hospital:title:manage'}}[key.value]??{title:'主数据',endpoint:'/admin/master/hospitals',permission:''}));
const form=reactive<Record<string,any>>({}); function reset(row?:Record<string,any>){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{status:true,published:false,sortOrder:0,version:row?.version??0},row??{});if(key.value==='hospital')Object.assign(form,{code:row?.hospitalCode??'',name:row?.name??'',hospitalLevel:row?.hospitalLevel??'UNKNOWN'});if(key.value==='campuses')Object.assign(form,{hospitalId:row?.hospitalId??'',code:row?.campusCode??'',name:row?.name??''});if(key.value==='departments')Object.assign(form,{organizationId:row?.organizationId??'',administrativeDepartmentId:row?.administrativeDepartmentId??'',hospitalId:row?.hospitalId??'',parentId:row?.parentId??null,code:row?.departmentCode??'',name:row?.name??''});if(key.value==='doctors')Object.assign(form,{doctorNo:row?.doctorNo??'',name:row?.name??'',titleId:row?.titleId??null,departmentIds:(row?.departments??[]).map((x:any)=>x.id).join(','),primaryDepartmentId:(row?.departments??[]).find((x:any)=>x.isPrimary)?.id??null,specialtyIds:(row?.specialties??[]).map((x:any)=>x.id).join('')});if(key.value==='dictionaries')Object.assign(form,{code:row?.code??'',name:row?.name??'',description:row?.description??''});}
async function load(){loading.value=true;error.value='';try{const r=await http.get(meta.value.endpoint,{params:key.value==='doctors'?{page:1,pageSize:50}:undefined});const data=r.data.data;rows.value=Array.isArray(data)?data:data.records;total.value=data.total??rows.value.length;}catch(e:any){error.value=e.message??'加载失败';}finally{loading.value=false;}}
function open(row?:Record<string,any>){editing.value=row??null;reset(row);visible.value=true;} function ids(value:any){return String(value??'').split(',').map(x=>Number(x.trim())).filter(Boolean)}
async function save(){try{let payload:any={...form};if(key.value==='doctors'){payload.departmentIds=ids(form.departmentIds);payload.specialtyIds=ids(form.specialtyIds);payload.primaryDepartmentId=Number(form.primaryDepartmentId);}if(editing.value){await http.put(`${meta.value.endpoint}/${editing.value.id}`,payload);}else{await http.post(meta.value.endpoint,payload);}ElMessage.success('已保存');visible.value=false;await load();}catch(e:any){ElMessage.error(e.response?.data?.message??'保存失败');}}
async function disable(row:Record<string,any>){try{await ElMessageBox.confirm(`确认停用“${row.name}”吗？`, '确认操作',{type:'warning'});const resource=key.value==='campuses'?'campus':key.value==='departments'?'department':key.value==='doctors'?'doctor':key.value==='hospital'?'hospital':'title';await http.post(`/admin/master/${resource}/${row.id}/disable`);await load();}catch{}}
const columns=computed(()=>key.value==='doctors'?['doctorNo','name','title','published','status']:key.value==='departments'?['departmentCode','name','category','doctorCount','published','status']:key.value==='campuses'?['campusCode','name','address','published','status']:key.value==='hospital'?['hospitalCode','name','hospitalLevel','published','status']:['code','name','description','published','status']);
watch(key,load);onMounted(load);
</script>
<template><section><div class="toolbar"><div><h2>{{meta.title}}</h2><p>所有列表与写操作均使用真实医院主数据 API。</p></div><el-button type="primary" @click="open()">新建</el-button></div><el-alert v-if="error" :title="error" type="error" show-icon/><el-skeleton v-else-if="loading" :rows="5" animated/><el-empty v-else-if="!rows.length" description="暂无数据，可从这里建立主数据"/><el-table v-else :data="rows"><el-table-column v-for="column in columns" :key="column" :prop="column" :label="column"/><el-table-column label="操作" width="170"><template #default="scope"><el-button link type="primary" @click="open(scope.row)">编辑</el-button><el-button link type="danger" @click="disable(scope.row)">停用</el-button></template></el-table-column></el-table><el-dialog v-model="visible" :title="editing?'编辑':'新建' + meta.title" width="600px"><el-form label-position="top"><template v-if="key==='hospital'"><el-form-item label="医院编码"><el-input v-model="form.code" :disabled="!!editing"/></el-form-item><el-form-item label="医院名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="医院等级"><el-select v-model="form.hospitalLevel"><el-option value="UNKNOWN" label="未评定"/><el-option value="TERTIARY_A" label="三级甲等"/><el-option value="TERTIARY_B" label="三级乙等"/><el-option value="NOT_APPLICABLE" label="不适用"/></el-select></el-form-item></template><template v-else-if="key==='campuses'"><el-form-item label="医院 ID"><el-input v-model="form.hospitalId"/></el-form-item><el-form-item label="院区编码"><el-input v-model="form.code" :disabled="!!editing"/></el-form-item><el-form-item label="院区名称"><el-input v-model="form.name"/></el-form-item></template><template v-else-if="key==='departments'"><el-form-item label="医院 / 行政组织 / 行政科室 ID"><el-input v-model="form.hospitalId" placeholder="医院 ID"/><el-input v-model="form.organizationId" placeholder="组织 ID"/><el-input v-model="form.administrativeDepartmentId" placeholder="行政科室 ID"/></el-form-item><el-form-item label="上级医疗科室 ID（可选）"><el-input v-model="form.parentId"/></el-form-item><el-form-item label="科室编码"><el-input v-model="form.code" :disabled="!!editing"/></el-form-item><el-form-item label="科室名称"><el-input v-model="form.name"/></el-form-item></template><template v-else-if="key==='doctors'"><el-form-item label="医生编号"><el-input v-model="form.doctorNo" :disabled="!!editing"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.name"/></el-form-item><el-form-item label="职称 ID"><el-input v-model="form.titleId"/></el-form-item><el-form-item label="科室 ID（逗号分隔）"><el-input v-model="form.departmentIds"/></el-form-item><el-form-item label="主科室 ID"><el-input v-model="form.primaryDepartmentId"/></el-form-item><el-form-item label="专业 ID（逗号分隔）"><el-input v-model="form.specialtyIds"/></el-form-item><el-form-item label="公开简介"><el-input v-model="form.profile" type="textarea"/></el-form-item></template><template v-else><el-form-item label="编码"><el-input v-model="form.code" :disabled="!!editing"/></el-form-item><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea"/></el-form-item></template><el-form-item label="排序"><el-input-number v-model="form.sortOrder" :min="0"/></el-form-item><el-form-item><el-checkbox v-model="form.status">启用</el-checkbox><el-checkbox v-model="form.published">向患者端发布</el-checkbox></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template><style scoped>.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.toolbar h2{margin:0}.toolbar p{color:#718096;margin:6px 0 0}</style>
